with kept_keys as (select method, order_id from payments intersect all select method, order_id from payments where status = 'FAILED'), reconciled as (select s.* from payments s inner join kept_keys k on s.method = k.method and s.order_id = k.order_id) select case when amount >= 1340 then 'HIGH' else 'LOW' end as amount_tier, size(collect_set(status)) as num_status, avg(amount) as avg_amount, count_if(status = 'FAILED') as failed_events, min(paid_at) as first_paid_at, count(*) as row_count from reconciled group by cube (case when amount >= 1340 then 'HIGH' else 'LOW' end) having row_count < 1000 order by avg_amount asc;
